import{a as o,t as i}from"./disclose-version.C5w_TsND.js";import"./legacy.BMQjkQkY.js";import{n as a}from"./runtime.BqgfhrT4.js";const r={title:"ERA-IX 100Gbit Port Upgrade for low-latency connectivity and DDoS Protection",description:"Faster connections to key providers on the ERA-IX platform and increased capacity for DDoS protection filtering and increased demand.",date:"Oct 10 2023",heroImage:"era-ix.webp",author:"Dries Degreef"};var n=i("<p><strong>On October the 3rd we’ve upgraded our ERA-IX port to 100Gbit to accommodate increasing demand and improve latency to key providers such as Hetzner, Cloudflare, Google, Steam and Meta. Traffic using ERA-IX will also be using our new filtering technologies.</strong></p> <h2>Why ERA-IX?</h2> <p>ERA-IX is a reliable and fast growing internet exchange with the ambition to expand and innovate making them an ideal partner for RoyaleHosting as we share the same vision and values. ERA-IX offers RoyaleHosting a low-latency connection to many key providers while offering many important insights and security features, this is why ERA-IX is our preferred route to these important providers.</p> <p>During the 100Gbit upgrade process, ERA-IX has been very helpful and flexible, ensuring a seamless transition to the new port.</p> <h2>Benefits for our customers</h2> <p>As we’ve already stated before, latency to key providers such as Hetzner, Cloudflare, Google, Steam and Meta will greatly improve as we’re directly connected to these providers via the ERA-IX platform. This was already the case before but due to the lower port capacity, not all traffic used the faster route.</p> <h2>Increased capacity</h2> <p>The addition of 100Gbit will allow us to handle more traffic during peak hours. This extra capacity will also increase our in house ddos protection filtering capabilities.</p> <h2>Conclusion</h2> <p>We’re very excited to be using the ERA-IX platform to provide our customers with lower latency connectivity and build out our own network infrastructure, this is one of the changes we’re making to improve our overall network infrastructure including DDoS protection.</p>",1);function s(e){var t=n();a(18),o(e,t)}const G=Object.freeze(Object.defineProperty({__proto__:null,default:s,metadata:r},Symbol.toStringTag,{value:"Module"})),l={title:"How we mitigated over 150 thousand DDoS attacks in 1 year and learned from them.",description:"During the last 12 months RoyaleHosting has mitigated over 150 000 DDoS attacks without any network interruptions for the customer.",date:"Oct 17 2022",heroImage:"150kattacks.webp",author:"Dries Degreef"};var c=i(`<p><strong>RoyaleHosting has been the goto provider for protection against attacks for a while now, DDoS protection has also been one of our main priorities and we’ve allocated a massive amount of resources into improving the DDoS protection to filter sophisticated and volumetric attacks.</strong></p> <br> <h2>Increase in DDoS Attacks</h2> <p>During the past year RoyaleHosting has seen a tremendous amount of growth, we had to drastically increase our network capacity and improve our infrastructure to support the growth. With this growth we also noticed an increase in both the amount and sizes of DDoS attacks targetting our customers.</p> <p><img src="/articles/150kattacks/attacks.webp" alt="DDoS Attacks"></p> <br> <br> <h2>Infrastructure Rebuild</h2> <p>In August 2021 we completely rebuilt our infrastructure and DDoS mitigation approach, from then on we would use Corero as our primary DDoS protection layer as they’re one of the best options to filter high capacity volumetric attacks reaching multiple terabits a second. Like most general protection layers Corero isn’t perfect and might still let a low amount of DDoS traffic through that can cause harm to the applications running on the servers of our customers. This is why we created a second DDoS protection layer in-house to counter bypass attacks that could not be filtered by Corero.</p> <br> <h2>Application Shield</h2> <p>The Application Shield is a custom-built DDoS protection layer that is built into our network infrastructure. We’re using this layer to protect our customers from sophisticated attacks targetting specific Applications like game servers, VPN servers, web applications, and more. The Application Shield is built to filter attacks that bypass other protection layers that can still cause harm to the applications running on the servers of our customers.</p> <p><img src="/articles/150kattacks/applicationshieldtraffic.webp" alt="Application Shield Usage"></p> <small>Screenshot of the Application Shield dropping DDoS traffic.</small> <p>One of the most important things with the application shield is performance, since the application shield makes use of advanced filtering techniques that are heavy for a CPU to handle it’s important to offload as much to the server NIC as possible. This is why we’re using Mellanox ConnectX-4/Netronome NICs in our servers to offload the filtering to the NICs. This allows us to filter attacks with a very low impact on the CPU and memory usage of the server. This caused a massive improvement in performance for our customers and allowed us to filter attacks that would have been impossible to filter before.</p> <p><img src="/articles/150kattacks/cpuusage.webp" alt="CPU Usage"></p> <small>Screenshot of CPU usage on the Application Shield servers during an attack.</small> <br> <br> <h2>Firewall Panel</h2> <p>One of the last things we set out to do was give our customers the ability to manage their own service firewall, we think it’s important to give our customers full control and visibility about what’s going on so our customers can take action without needing our help. To achieve this goal we created our shield panel that allows our customers to manage their network firewall via an easy-to-use and simple interface.</p> <p><img src="/articles/150kattacks/shieldpanel.webp" alt="Application Shield Usage"></p> <small>Screenshot of a beta version of the firewall panel.</small> <h2>The importance of good application DDoS Protection</h2> <p>Many hosting providers offer high-capacity volumetric DDoS mitigation but as highlighted above it’s really important to have a solid mitigation solution for application based attacks.
By utilizing the RoyaleHosting network you can be sure that your server and application will stay online no matter what, our team is always happy to assist with building custom DDoS protection for your needs! (<a href="https://royalehosting.net/submitticket.php" target="_blank">Contact our team</a>)</p>`,1);function u(e){var t=c();a(48),o(e,t)}const F=Object.freeze(Object.defineProperty({__proto__:null,default:u,metadata:l},Symbol.toStringTag,{value:"Module"})),h={title:"Partnering with Arelion the Leader for Global Connectivity",description:"We have partnered with Arelion for their leading global connectivity with key providers, renowned for excellence. Allowing for low-latency connectivity across the globe.",date:"May 16 2024",heroImage:"arelion-transit.webp",author:"Jack Holmes"};var d=i('<p>We are incredibly excited to announce a significant improvement in low-latency global connectivity. We’ve recently formed a partnership with <a href="https://www.arelion.com/" target="_blank" rel="noreferrer noopener">Arelion</a>, a premier transit provider that will improve the quality of international connectivity for our customers.</p> <p>Along with adding Arelion, we have added more capacity to strengthen our infrastructure. Arelion is now a critical part of our network for low-latency transits. We want to ensure that we always have the most outstanding network available for our customers, and introducing Arelion as a transit provider backs up those claims.</p> <h2>Who is Arelion and Why Now?</h2> <p>Arelion, previously known as Telia, is a noteworthy player in the connectivity space. They provide premium transit services for organizations.</p> <p>Arelion’s national IP backbone networks are the largest in the Nordic and Baltic regions. Their connectivity backbone has been improved steadily since 1991. It’s one of the largest in Europe and even worldwide. This conveys that they will provide our customers with the best possible, fastest traffic routing with the fewest number of AS hops.</p> <p>Arelion has 70,000km of optical fiber routes, and as a fun fact, they have more than 45,000 customers in 125 countries.</p> <p>We have implemented Arelion as a transit provider to improve customer connectivity. As Arelion focuses on a global scale, this will allow us to better cater to a worldwide audience in the hosting industry.</p> <h2>Conclusion</h2> <p>It has been a wonderful experience working with Arelion, and we are excited for our customers to experience this new change. We are looking forward to the opportunities that this collaboration will bring to improve our customers’ connectivity and hosting experiences for many years to come.</p>',1);function p(e){var t=d();a(16),o(e,t)}const L=Object.freeze(Object.defineProperty({__proto__:null,default:p,metadata:h},Symbol.toStringTag,{value:"Module"})),m={title:"Strategic Partnership with Corero for DDoS Protection at RoyaleHosting",description:"Partnering with Corero for their industry-leading on-site DDoS threat mitigation devices, offering best-in-class DDoS protection.",date:"May 16 2024",heroImage:"corero-protection.webp",author:"Jack Holmes"};var g=i('<p>We’re thrilled to announce that we have partnered with <a href="https://www.corero.com/" target="_blank" rel="noreferrer noopener">Corero</a> to integrate their industry-leading DDoS threat mitigation solution into our hosting services. This marks a significant milestone in our commitment to providing our customers with the best possible DDoS protection and service.</p> <p>Previously, we relied on Corero for protection, but our previous transit provider stopped offering Corero’s protection in favor of their own. This decision has affected our mitigation efforts, so we have established a direct partnership with Corero to ensure we have the same, if not better, protection.</p> <p>With the introduction of self-owned Corero devices, we are in complete control. The protection offered by Corero is inline, meaning we drop traffic without increasing latency, minimizing ATM (Attack Mitigation Time).</p> <h2>Who is Corero and Why Now?</h2> <p>Corero is the leading company that offers automatic and real-time protection solutions against DDoS attacks. Their products are well-known for their exceptional DDoS protection and intelligent software that provides a seamless protection layer for network providers. Corero’s SmartWall technology delivers robust protection by examining each packet header and payload inline for quick, low-latency mitigation. These efforts guarantee DDoS attacks are identified and dropped quickly without affecting legitimate traffic.</p> <p>We decided to integrate Corero’s DDoS protection due to the increasing frequency, magnitude, and complexity of DDoS attacks on our network. Switching from our previous provider was necessary, and Corero was our perfect choice. Corero’s approach to DDoS protection is impressive, providing real-time detection and line-rate mitigation.</p> <p>Working with Corero was a pleasure. Their technology outperformed others, leading us to become a valued customer.</p> <p>So what does this mean for you? With Corero’s DDoS protection systems in place, you can expect:</p> <ul><li><strong>Low Latency Mitigation:</strong> Corero’s systems ensure legitimate traffic flows smoothly, maintaining optimal latency for your applications.</li> <li><strong>Inline DDoS Protection:</strong> Corero’s SmartWall technology inspects every packet at a line rate, providing superior visibility and swift, automatic mitigation.</li> <li><strong>Always-On Protection:</strong> Corero’s systems remain vigilant 24/7, safeguarding your services from even the most sophisticated attacks.</li> <li><strong>Resolution of Current DDoS Mitigation Issues:</strong> Any previous DDoS mitigation challenges you may have faced are now a thing of the past.</li> <li><strong>Improved RoyaleHosting Shield Panel:</strong> Our shield panel has been updated to accommodate more in-depth information, thanks to Corero’s reporting (with more functionality being integrated in the coming months).</li></ul> <h2>Conclusion</h2> <p>We’re excited about this new addition to our services and look forward to continuing to provide our customers with the best hosting solution. This is currently live in Amsterdam, and we plan to have New York also covered by the end of the month (May).</p> <p>As a result of implementing Corero, our upstream connectivity has improved, offering lower latency and a more robust overall network. For more information, you can read our in-depth blog posts about <a href="/blog/arelion-upstream-provider">Arelion</a> and <a href="/blog/ntt-upstream-provider">NTT</a>.</p> <p>Thank you for choosing RoyaleHosting as your trusted provider. We’re committed to operating efficiently and protecting your services from potential DDoS attacks.</p>',1);function f(e){var t=g();a(24),o(e,t)}const B=Object.freeze(Object.defineProperty({__proto__:null,default:f,metadata:m},Symbol.toStringTag,{value:"Module"})),w={title:"Customizable VPS Hosting Solutions at RoyaleHosting",description:"Save with RoyaleHosting's customized VPS hosting solutions. Offering customized and tailor-made VPS hosting solutions with better performance than OVH Cloud.",date:"Dec 17 2023",heroImage:"vps-solution.webp",author:"Jack Holmes"};var y=i(`<p>Are you tired of one-size-fits-all VPS solutions? Every business has unique needs and requires a server that can be tailored to meet these specific requirements. At RoyaleHosting, we understand this and offer customizable VPS solutions that put you in control.</p> <br> <h2>🤔 Why is Customization Important?</h2> <p>Customization empowers you to create your VPS to fit your precise requirements. This ensures you only pay for what you use, eliminating the cost of superfluous features. Unlike other providers that offer pre-set servers, we give you the freedom for tailored VPS hosting.</p> <p>A tailored VPS hosting allows you to:</p> <ul><li>Customize the VPS to align with the business requirements.</li> <li>Choose the resources such as RAM, CPU and Storage based on specific demands.</li> <li>Pay for the features and resources you select, eliminating unnecessary expenses.</li> <li>Quickly scale resources up or down based on fluctuating demands, ensuring optimal performance.</li> <li>Customise firewall settings and other security features to defend against potential threats robustly.</li> <li>Choose from a large selection of available operating systems.</li> <li>View essential metrics of the server’s well-being on an easy-to-navigate control panel.</li></ul> <p>Our customers who move to RoyaleHosting typically save an impressive 184% compared to providers like OVH Cloud or Vultr, as it’s a customizable VPS solution.</p> <br> <h2>🫡 Our Commitment to Transparency in Hosting</h2> <p>At RoyaleHosting, transparency is more than just a trendy term - it’s a pledge. We firmly believe that you should know what you’re investing in. That’s why we provide clear information about the CPUs and hardware deployed in our VPS nodes before you pay, a degree of transparency many providers fail to offer.</p> <p>We acknowledge that the efficiency and dependability of your VPS hosting solution heavily rely on the underlying hardware. Being open about our hardware empowers you to make well-informed decisions regarding your hosting solutions. You’ll know what you’re signing up for without hidden shocks or deceptive promises.</p> <p>This transparency extends to all aspects of our service. We aim to provide clear, honest, and open communication from pricing to customer support. This is one of the many ways we strive to build trust with our customers and provide a superior hosting experience.</p> <br> <h2>👨‍🏭 Industry-leading DDoS Protection</h2> <p>Having a DDoS-protected VPS server is vital to ensure that your business remains operational. Hence, our VPS servers come equipped with advanced 2.5Tb/s DDoS protection, which is the industry’s best. Our protection system can handle high volumes of traffic without affecting your server’s performance. This level of protection is unmatched and provides unparalleled security to your servers.</p> <p>We fully understand the significance of DDoS protection in the hosting industry. Without protection, servers cannot function 24/7. Therefore, we aim to benchmark digital acceptance for DDoS protection. Uninterrupted services are not a luxury - it’s a necessity. And with RoyaleHosting, it’s a promise.</p> <br> <h2>🛡️ The Power of Our Shield Panel</h2> <p>Our advanced shield panel goes hand-in-hand with managing your Virtual Private Server.</p> <p>Having control and insight into your server’s traffic is crucial. No questions asked. That’s where our comprehensive Shield Panel comes into play.
Designed with our customers in mind, the Shield Panel is more than just a control panel - it’s a powerful tool that puts you in the driver’s seat.</p> <p>Our Shield Panel allows you to manage and fine-tune your settings on our edge network easily. This means you can adjust your server’s settings to filter high-capacity traffic, ensuring that only legitimate traffic reaches your server. This level of control is essential in today’s digital landscape, where cyber threats are increasingly sophisticated and common.</p> <p>But the Shield Panel isn’t just about control - it’s also about insight. With our powerful tools, you can gain valuable insights into the attacks your server is facing. You can analyze and understand the traffic directed towards your server, helping you identify patterns, anticipate threats, and strengthen your defenses.</p> <p>The Shield Panel is currently in beta. If you’re a customer and wish to test it out and submit feedback on its effectiveness in your business, submit a ticket, and we can grant you access.</p> <br> <h2>✨ Intuitive VPS Manager</h2> <p>Have you ever wrestled with a hosting service that has a cumbersome, slow, and glitchy control panel with poor security? We understand how exasperating it can be to navigate a system that’s more of a headache than a help and requires extensive learning with poor user experience. That’s why at RoyaleHosting, we’ve built our own VPS manager from scratch to tackle these issues.</p> <p>Our VPS manager is designed with the user experience at its heart. It’s intuitive, speedy, bug-free, and reliable, making managing your server a breeze. Whether you’re a tech-savvy expert or a novice, you’ll find our VPS manager straightforward and user-friendly.</p> <p>But user-friendliness doesn’t mean we’ve skimped on features. Our VPS manager is fully featured and grants you complete control over your server. You can do everything from monitoring and managing your server’s resources to adjusting settings with just a few clicks.</p> <p>Furthermore, we’ve ensured that our VPS manager has incredible security. With robust security measures, you can have peace of mind knowing your server is safe. At RoyaleHosting, we believe that managing your server shouldn’t be a burden. With our user-friendly VPS manager, it’s a cinch.</p> <br> <h2>🌎 Global Server Locations</h2> <p>Our VPS servers are strategically located in two major financial hubs: New York and Amsterdam. This allows for low latency and fast connection speeds for US or European businesses, providing optimal performance and connectivity.</p> <p>We have optimized routing to ensure a low latency and incredible experience wherever you are.</p> <br> <h2>👩‍💻 24/7 Live Chat & Ticket Support</h2> <p>Outstanding customer service should be the norm, and we deliver efficient 24/7 live chat technical support without lengthy wait times.</p> <p>Our customers frequently commend our support team for their swift response times. We understand that every minute is precious when grappling with an issue. That’s why we endeavor to respond to all inquiries promptly. But swift responses don’t equate to hasty service - we take the time to comprehend your issue and provide a thorough solution.</p> <p>We take pride in the support we extend to our customers. This dedication to exceptional customer service distinguishes us in the VPS hosting industry. But don’t just take our word for it - our customers’ feedback on Trustpilot attests to this.</p> <br> <h2>⭐ Trustpilot Reviews Speak for Themselves</h2> <p>We take pride in offering exceptional service and dependable, personalized VPS solutions, reflected in our impressive 4.8-star rating based on 400~ reviews on Trustpilot. Our contented customers have shared numerous positive reviews highlighting our commitment to satisfying their essentials.</p> <a href="https://www.trustpilot.com/review/royalehosting.nl" target="_blank" rel="noreferrer noopener">View our Trustpilot to learn why we’re the best -></a> <br> <br> <h2>👩‍💻 Conclusion</h2> <p>At RoyaleHosting, we are more than just an ordinary hosting. We strive to be your partner, offering an experience like no other. We believe in the freedom of choice and offer fully customizable VPS servers to meet your specific requirements.</p> <a href="https://royalehosting.net/store/vps/new" target="_blank">Try our customizable VPS solution now -></a>`,1);function v(e){var t=y();a(92),o(e,t)}const X=Object.freeze(Object.defineProperty({__proto__:null,default:v,metadata:w},Symbol.toStringTag,{value:"Module"})),b={title:"New Website: Improved user experience, more functionality and better integration",description:"An overview of the new RoyaleHosting website, the features it has to offer, how it's build and what we have planned for the future.",date:"June 23 2023",heroImage:"newsite.webp",author:"Dries Degreef"};var k=i('<p><strong>Our previous website has been significantly overdue for an update as our product lineup and goals have shifted over the years. In early 2022 we started development on an entirely new website that would be built from scratch and use our new core system with our goal to have better integration and possibilities to develop innovative new features.</strong></p> <br> <h2>One Website</h2> <p>royalehosting.net is now the only website that can be used to order and manage services, in the past royalehosting.nl was a seperate website that also allowed ordering and managing services which caused confusion for some users. We have now merged both websites into one. All the services that were previously available on royalehosting.nl are now available on royalehosting.net and you’re able to login with your royalehosting.nl account on royalehosting.net.</p> <br> <h2>New Features</h2> <p>With the first release of our website we’ve focused on implementing most features that were available on our previous website without many new features to ensure a smooth transition. However we have added a few new features such as:</p> <ul><li>Drastically improved user-experience.</li> <li>New Modern UI</li> <li>New Product Lineup</li> <li>Improved VPS configurator</li> <li>Easier way to renew services</li> <li>Adjusted price when ordering for longer periods</li></ul> <br> <h2>Features to come</h2> <p>In the comming months we will be working on implementing new features and improving existing features such as:</p> <ul><li>Shield account syncronization</li> <li>Automatic Dedicated Server provisioning</li> <li>IP Manager</li> <li>Billing API</li> <li>Dedicated Server Configurator</li> <li>Improved alert system</li> <li>Language localization</li></ul> <br> <h2>New Design</h2> <p>Our new website has been designed from the ground up to be more informative and representative of our brand with a user-centric approach, intuitive and efficient navigation system, better accesability and an overall sleek and moderen design.</p> <br> <h2>Technologies</h2> <p>When building the new website we opted to use bleeding edge technologies and step away from more traditional technologies such as PHP. We’ve made this descision to future proof our website and ensure high performance and scalability.</p> <h2>New Lineup</h2> <p>We have made the decision to discontinue product categories that do not align with RoyaleHosting’s direction. Additionally, we have introduced new products to our dedicated lineup, complete with updated pricing. This change anticipates the arrival of instant deployment servers. Moreover, we have included previously available but unsold categories like colocation on our website.</p> <h2>Footnote</h2> <p>We expect the site to have many bugs and issues in the first few weeks, if you find any you can contact us via the <a href="https://royalehosting.net/support" rel="nofollow">site</a> or in <a href="https://discord.gg/royalehosting" rel="nofollow">discord</a>.</p>',1);function S(e){var t=k();a(42),o(e,t)}const J=Object.freeze(Object.defineProperty({__proto__:null,default:S,metadata:b},Symbol.toStringTag,{value:"Module"})),_={title:"New VPS Manager: Faster, smoother, seamless integration and more functionality",description:"An overview of the new in-house developed VPS Manager, why we spend time developing this and what we have planned for the future.",date:"Sep 4 2023",heroImage:"vpsmanager.webp",author:"Dries Degreef"};var D=i(`<p><strong>On September the 5th we’re releasing our new VPS manager that has been in development for quite a while, this will be another milestone in transitioning all our software to in house developed solutions and we’re excited to offer new innovative features to our customers.</strong></p> <br> <h2>Why we developed our own VPS Manager</h2> <p>The demand for virtual private servers has gone up exponentially in the last few months, as our demand increased we noticed that our current VPS panel couldn’t keep up and started causing many stability and performance issues for our customers.</p> <p>As we recently switched to our own core/billing system we’re able to integrate a in-house developed VPS manager much better than what is currently possible.</p> <p>To improve our services and integration with our core/billing system we started development on a new VPS manager that will solve all issues that are currently present on our old panel and will allow us to offer new innovative features.</p> <br> <h2>New Node Specfications</h2> <p>We’re committed to exclusively utilize high performance enterprise hardware including NVME SSD’s, Intel Xeon Gold/Platinum or AMD EPYC CPU’s and DDR4/DDR5 ECC memory, starting with two brand new nodes in Amsterdam and New York. This will ensure high performance and reliability at all time.</p> <br> <h2>What’s new?</h2> <b class="block">Console</b> The new console allows you to quickly access your VPS via the browser, this is a lot more stable and faster than before. <b class="block">IP Address Management</b> You're now able to directly manage your ip addresses via the VPS manager, this allows you to change the rDNS name directly without having to use the shield panel. <b class="block">Snapshots</b> You can now create snapshots of your VPS to backup the current state of the server. <b class="block">Improved insights</b> On the homepage you're able to view the following metrics: <ul><li>CPU Usage</li> <li>Memory Usage</li> <li>Disk Usage</li> <li>Network Usage</li></ul> <br> <h2>What’s next?</h2> <p>We’ve got many things planned for the new VPS manager including an automation manager to automatically perform actions on your server, an easy to use API, sub accounts and a software installer. We’re also planning on releasing the 1.0 version of our shield panel soon and we’re working on a new dedicated manager, colocation manager and a reseller platform.</p> <br> <h2>What about customers using the old panel?</h2> <p>You can migrate your VPS to the new VPS manager by creating a ticket, however the old VPS will be deleted and all data will be lost, you will also receive a new IP address.
We’re not planning on migrating away from our old panel anytime soon, so servers on the old panel will continue to work for the foreseeable future.</p> <h2>Conclusion</h2> <p>Our new VPS manager will drastically improve the customer experience with new innovative features on a more stable and performant platform. We’re excited to find out what you think about our new VPS manager.</p>`,1);function T(e){var t=D();a(46),o(e,t)}const Y=Object.freeze(Object.defineProperty({__proto__:null,default:T,metadata:_},Symbol.toStringTag,{value:"Module"})),x={title:"Partnering with NTT to Improve Global Connectivity",description:"We have partnered with NTT for their industry-leading, renowned connectivity offerings. Allowing for low-latency global connectivity",date:"May 16 2024",heroImage:"ntt-transit.webp",author:"Jack Holmes"};var W=i('<p>We are delighted to inform you about some exciting news. We’re on a significant journey to enhance your connectivity as a customer. As a result of this journey, we have partnered with <a href="https://services.global.ntt/" target="_blank" rel="noreferrer noopener">NTT</a>, a leading transit provider renowned for excellence. This partnership is a milestone for us to provide outstanding global connectivity.</p> <p>This partnership is long-term to improve connectivity globally for our customers. Our partnership with NTT delivers considerably better networking for all RoyaleHosting customers.</p> <h2>Who is NTT and Why Now?</h2> <p>NTT (Nippon Telegraph and Telephone) is a leading global information and communication technology solutions provider. They offer secure and reliable access worldwide, including comprehensive solutions for edge computing, private 5G, and IoT, all backed by a robust infrastructure. NTT delivers comprehensive data-led insights that help organizations worldwide improve connectivity.</p> <p>Our internal talks with NTT have been easy, and their team is highly responsive in addressing our needs. Their quick and efficient setup has dramatically improved our network capabilities, allowing us to implement them as a transit swiftly. We are impressed by their level of service and would like to thank them for their shared sentiments for RoyaleHosting.</p> <p>NTT’s reputation as a transit provider has been beneficial in creating our long-term connectivity strategy. We have found that NTT is committed to the same level of excellence as we are.</p> <p>We have hit a significant milestone on our journey to deliver top-tier connectivity solutions. NTT looks to become a driving force and push the boundaries of global connectivity excellence. We will lean on this excellence to enhance our network infrastructure and deliver our customers the most remarkable connectivity experiences.</p> <h2>Conclusion</h2> <p>NTT’s global leading, low-latency connectivity will be a significant step towards enhancing RoyaleHosting’s services. As we take this opportunity, we thank our customers for your persistent support in allowing us to flourish as a company. We’re eagerly looking forward to an exciting future ahead of us.</p>',1);function P(e){var t=W();a(16),o(e,t)}const Q=Object.freeze(Object.defineProperty({__proto__:null,default:P,metadata:x},Symbol.toStringTag,{value:"Module"})),A={title:"RoyaleHosting Q4 2024: New Office, Custom Data Center, and Major Network Upgrades",description:"Exciting developments as RoyaleHosting expands with a new office space, custom data center room, and significant network infrastructure upgrades.",date:"October 28 2024",heroImage:"royalehosting-2024-q4.webp",author:"Jack Holmes"};var C=i(`<p>Hey everyone! We’ve been quietly working on some massive developments behind the scenes, and we’re thrilled to finally share what’s coming to RoyaleHosting in Q4 2024. While this year has already seen significant growth and improvements, we’re about to take things to a whole new level.</p> <h2>Expanding Operations with Enhanced Office Space</h2> <p>We’re expanding our operational footprint with a larger, more capable office facility. This expansion goes beyond additional square footage – it’s about elevating our operational capabilities to match our growing service offerings (and yes, we’ve upgraded the coffee machines too ☕).</p> <p><img src="/articles/royalehosting-2024-q4-plans/new-office.webp" alt="New Office Space"></p> <small>Photo of our new office facility being built.</small> <p>The expanded facility features an enhanced hardware storage area, significantly improving our deployment efficiency. By scaling up our on-site inventory management, we can further reduce deployment times and respond even more quickly to customer needs.</p> <p>One of the most exciting improvements is our enhanced inventory management system, complete with an expanded testing facility. This allows us to maintain our thorough hardware testing processes at a larger scale, documenting each step meticulously. Although our suppliers test rigorously, we always double-check to reduce shipping inflicted issues which may occur (and catch those sneaky “factory features” that sometimes slip through 😉).</p> <p>We’re also upgrading our Network Operations Center (NOC) with advanced monitoring capabilities, ensuring 24/7 oversight of our infrastructure with unprecedented detail.</p> <h2>New Custom Data Center Room</h2> <p>The cornerstone of our Q4 developments is our custom-built data center room, designed from the ground up to meet our exact specifications and future requirements. Every cable run, every rack position, and every power distribution point has been carefully planned to maximize efficiency and reliability.</p> <p><img src="/articles/royalehosting-2024-q4-plans/new-datacenter-room.webp" alt="New Data Center Room"></p> <small>Picture of our new data center room, before it's taken down and rebuilt to meet our custom requirements.</small> <p>Our new data center space represents a significant leap forward in how we deliver our services. We’ve designed it with instant deployments in mind, adding substantial rack capacity that allows us to respond to customer needs faster than ever before. The entire network architecture has been reimagined, incorporating automation at every level to streamline operations and reduce human error.</p> <p>Security was a top priority in our design process. We’ve implemented enhanced infrastructure security measures that give us complete control over the environment. This isn’t just about physical security – it’s about creating a controlled environment with us at the helm.</p> <p>Looking to the future, we’ve built this space with scalability in mind. Our infrastructure has been designed to support over 10Tbps of connected capacity, ensuring we can rapidly scale up as demand grows. This forward-thinking approach allows us to expand our capabilities on short notice while maintaining the exceptional service quality you expect from us.</p> <p>Perhaps most exciting is the new network layout we’ve implemented. It’s been specifically designed to support our new dedicated server manager, which will be an invaluable upgrade to how customers interact with their dedicated machines.</p> <h2>Upgraded Network Infrastructure</h2> <p>Our network infrastructure is undergoing its most significant upgrade yet, and we couldn’t be more excited about what this means for our customers.</p> <p><img src="/articles/royalehosting-2024-q4-plans/new-switches.webp" alt="New Network Upgrades"></p> <small>Photo of our new Arista 32x 100G, 4x 400G routers and 64x 100G port spine switches.</small> <p>The headline feature with our network upgrade is our new 400Gbit port capability – a game-changer for customers with demanding throughput requirements. We’ve worked closely with major providers to expand our connectivity options, ensuring that this massive capacity is backed by robust, reliable connections to key network providers worldwide with industry-leading latency figures.</p> <p>Alongside these updates, we’ll be deploying an additional DDoS mitigation cluster for Application Shield, featuring enhanced filtering options. This new mitigation cluster will launch with 800 Gbps of filtering capacity, alongside our existing protection layers, with plans to scale up further in the future.</p> <h2>Impact on Service Delivery</h2> <p>All these infrastructure improvements aren’t just about having newer, shinier equipment – they’re about delivering tangible benefits to our customers. With our new office and testing facilities, we’ve significantly reduced hardware deployment times. When you need new services, we can respond faster than ever before, with equipment that’s been thoroughly tested and verified.</p> <p>Our enhanced DDoS protection capabilities mean better security for your services. The combination of our new mitigation cluster and advanced filtering technologies provides more robust protection against evolving threats, while maintaining the performance you expect from your services.</p> <p>The network upgrades we’re implementing open up new possibilities for high-performance applications. Whether you’re running resource-intensive workloads or need ultra-low latency connections, our expanded connectivity options and increased capacity ensure we can meet those demands.</p> <p>Behind the scenes, our upgraded NOC and monitoring systems mean we can spot and respond to potential issues faster than ever. This proactive approach to service management helps ensure your services run smoothly, with minimal interruption.</p> <p>Perhaps most importantly, these improvements pave the way for our new colocation and dedicated server managers. These new platforms will revolutionize how you interact with your infrastructure, providing full control and visibility over your services. Whether you’re managing colocated hardware or dedicated servers, these panels will make infrastructure management more intuitive and efficient for you and your employees.</p> <h2>Looking Forward</h2> <p>These Q4 developments represent more than just physical expansion – they’re a strategic investment in our future service capabilities. We’re building an infrastructure that not only meets current demands but is ready for the next generation of hosting requirements.</p> <p>We’ll be sharing regular updates as we implement these improvements throughout Q4 and into the following year. Stay tuned for some exciting posts along the way.</p> <p>Thank you for your continued trust in RoyaleHosting. We’re excited to bring these improvements online and demonstrate how they’ll enhance your experience with us.</p>`,1);function O(e){var t=C();a(62),o(e,t)}const K=Object.freeze(Object.defineProperty({__proto__:null,default:O,metadata:A},Symbol.toStringTag,{value:"Module"})),H={title:"RoyaleHosting at Cloudfest 2024: Join Us for a Future-Forward Cloud Conversation",description:"Join RoyaleHosting at Cloudfest 2024 in Germany for exciting cloud hosting conversations and opportunities.",date:"Jan 15 2024",heroImage:"cloudfest-2024.webp",author:"Jack Holmes"};var R=i("<p><strong>We are excited to share that RoyaleHosting, your provider of DDoS-protected server hosting, is preparing for Cloudfest 2024! The event takes place in Rust, Germany, at Europa Park.</strong></p> <h2>What is Cloudfest?</h2> <p>For those looking to become more familiar with Cloudfest, it is the premier event for leaders in the cloud-hosting industry to converge, converse, and celebrate the latest advancements in the hosting world. From March 18th to March 21st, the industry’s most radiant minds will gather to yank back the curtain on the future of the internet. We’re thrilled to be attending for the second year in a row.</p> <h2>Who will be there?</h2> <p>We are beyond excited to participate throughout the week and bring our team! Keep a lookout for the folks donning the RoyaleHosting brand:</p> <ul><li>CEO – Stan van de Klippe</li> <li>COO – Dries Degreef</li> <li>Jack Holmes (me) – your Lead of Product & Communications.</li></ul> <p>We look forward to connecting with other industry vets, forthcoming talents, and enthusiasts alike.</p> <h2>Why Come See Us?</h2> <p>Apart from diving into the latest cloud innovations, we are keen to engage in discussions that could shape the future of our business. As we scratch other experts’ shoulders and partake in enlightening talks, we’re equally enthusiastic about the one-on-one interactions that Cloudfest promotes.</p> <p>We’re not here only to listen but also to find enthusiasts who will improve our future as we connect with aspiring minds. We want to uncover new opportunities to help our current and future customers remain at peace with the growing threats of DDoS attacks while providing seamless connectivity.</p> <h2>Schedule a Meeting</h2> <p>If you plan to attend Cloudfest 2024 and would like to sit down with us, we encourage you to reach out. We’re open to scheduling meetings, back-and-forths, or even casual chats over coffee. Cloudfest is not only about the big presentations; it’s about the personal connections that drive our industry forward. The ideas shared in those private moments often catalyze ingenious advancements for businesses.</p> <p>We look forward to seeing you and many more at Cloudfest 2024!</p>",1);function I(e){var t=R();a(24),o(e,t)}const Z=Object.freeze(Object.defineProperty({__proto__:null,default:I,metadata:H},Symbol.toStringTag,{value:"Module"})),N={title:"RoyaleHosting in 2023: Equinix, Improved DDoS Protection, Connectivity and Software",description:"A brief overview of what RoyaleHosting will be doing in the coming year and a look into the past as RoyaleHosting turns 5 years old.",date:"Dec 31 2022",heroImage:"royalehosting2023.webp",author:"Dries Degreef"};var V=i(`<p><strong>It’s hard to believe, but RoyaleHosting is turning 5 years old! We’ve come a long way since our humble beginnings, and we couldn’t have done it without your support. We have lots of exciting things planned for 2023 and we want to talk about each one in this article.</strong></p> <br> <h2>5 Years of RoyaleHosting</h2> <p>As we celebrate our 5th anniversary at RoyaleHosting, we reflect on the journey that led us to where we are today. When we first started, our goal was to revolutionize the hosting industry by providing reliable and affordable services for all. However, we quickly realized that the providers we were relying on could not meet the high standards of reliability and performance that we desired for our customers.</p> <p>In response, we made the decision to build our own network and infrastructure, paving the way for us to offer the best possible service to our valued customers. Along the way, we faced many challenges and obstacles, but we persevered and were able to overcome them.</p> <p>Today, we are proud to say that our dedication to providing top-quality hosting services has paid off, however we are far from done. We have many exciting things planned for the future, and we can’t wait to share them with you!</p> <h2>Equinix</h2> <p>We are pleased to announce that at the start of 2023, we will be relocating all of our servers in the Netherlands to Equinix AM5, the world’s leading provider of data center services. This move will allow us to greatly improve the reliability and performance of our hosting services.</p> <p>In the past, we have faced many challenges with our previous data center provider that have limited our capabilities. With Equinix, we will be able to overcome the limitations of our previous data center and significantly increase the reliability of our services.</p> <p>We will do everything we can to minimize any potential disruptions during the transition period, there will soon be a followup announcement regarding more information about this move which will include a timeframe and all the other information regarding this move, this announcement will come 30 days before the datacenter migration. If you have any questions or concerns, please don’t hesitate to contact our support team.</p> <h2>DDoS Protection</h2> <p>Moving to equinix will also allow us to rebuild our core network infrastructure that will include a better way to mitigate DDoS attacks with lower latency and higher accuracy. This will also result in better logging and more options for our customers to mitigate DDoS attacks. We will be working hard to expand the functionality of the firewall panel as well as we’re slowly moving to the 1.0 version of the panel.</p> <h2>Future Projects</h2> <ol><li><h3>New site</h3> <p>As we’re working to modernize our entire infrastructure we want to modernize the way to interact with your services as well. This is why we’re working on a complete redesign of the website from the ground up, with a fresh new look and a more intuitive user interface. We’re also adding a number of new features and functionality to make it easier for you to manage your services and access the resources you need with direct integrations into the firewall panel and other future software.</p></li> <li><h3>More pop locations</h3> <p>We’ve received a lot of requests to offer services at more locations, that is why we are expanding our network to include even more POP locations around the world. In the next year, we will be opening new datacenter locations in Brussels, Frankfurt, Los Angeles, and Singapore to better serve our global customer base. These new locations will allow us to offer lower latency and higher performance for our hosting services, and we are confident that they will be a valuable addition to our network. While we are excited to bring these new locations online, we do not have an ETA at this time for when they will be fully operational. We will provide updates as they become available and appreciate your patience as we work to bring these new datacenters online.</p></li> <li><h3>Dedicated Panel</h3> <p>We are working on a brand new dedicated server panel that will be releasing in the coming months. Our previous dedicated server panel did not meet the high standards of user experience that we strive for, and we are dedicated to improving it. The new panel will be completely redesigned and will offer a range of new features and functionality to make managing your dedicated server easier and more efficient. With this new panel, we will be able to instantly deliver dedicated servers to our customers, providing a seamless and convenient experience. We are confident that this new panel will be a valuable resource for our dedicated server customers and will provide a much-improved user experience.</p></li> <li><h3>Colocation Panel</h3> <p>We are excited to announce the upcoming launch of our new colocation panel, which will provide our colocation customers with unparalleled control and monitoring of their services.
With this new panel, colocation customers will be able to manage their racks, including monitoring temperature and power usage, as well as access a range of networking features and monitoring tools. We believe that this new panel will be a valuable resource for our colocation customers and will provide an exceptional user experience.
We will be releasing the new colocation panel in the coming months together with the dedicated server panel, and we can’t wait for our customers to try it out.</p></li></ol> <br> <p>We want to extend a heartfelt thank you to all of our valued customers for your continued support and loyalty. We couldn’t have gotten this far without you, and we are grateful to have you as a part of our community.</p> <p>As we look to the future, we are excited about the growth and potential of our company. We are dedicated to continuously improving and expanding our services to provide the best possible hosting experience for our customers.</p> <p>Thank you again for choosing RoyaleHosting. We look forward to continuing to serve you with the highest level of service and support in the years to come. Here’s to an even brighter future for our company and for all of our customers.</p>`,1);function j(e){var t=V();a(34),o(e,t)}const ee=Object.freeze(Object.defineProperty({__proto__:null,default:j,metadata:N},Symbol.toStringTag,{value:"Module"})),q={title:"RoyaleHosting in 2024: Shield Panel Release, Nikhef Housing, Infrastructure Upgrades and Software",description:"An overview of what RoyaleHosting has planned for 2024 and a look into the past as RoyaleHosting turns 6 years old.",date:"Dec 31 2023",heroImage:"royalehosting-in-2024.webp",author:"Jack Holmes"};var z=i("<p>As we approach the twilight of an extraordinary 2023 and prepare to leap forward into 2024, RoyaleHosting has much to celebrate and even more to anticipate. This year, we marked our sixth year of unwavering commitment to top-notch hosting services, again witnessing the strength of our team’s resolve, expertise, and innovation.</p> <h2>Six Years of Delivering Excellence ⭐</h2> <p>Throughout our six-year journey, RoyaleHosting has been dedicated to setting ourselves apart as industry leaders in hosting services. This year, in particular, was filled with success and intense innovation. The successful launch of our new VPS manager is evidence of our commitment to continual improvement. Our Beta Shield Panel and internal Alpha Dedicated Panel are on a distinctive path to redefine firewalls and the dedicated customer experience, respectively.</p> <p>The past year was also a significant improvement in our infrastructure and DDoS protection, ensuring that we meet and exceed client expectations. Reflecting on the tireless efforts of our team, we are filled with an immense sense of fulfillment and pride. What further fuels our spirits is the eagerness to welcome 2024 and embrace the new challenges it brings, committed to delivering even greater excellence in the years ahead.</p> <h2>Expanding Our Locations: Hello Nikhef! 🏢</h2> <p>As we move into 2024, RoyaleHosting makes its presence felt at a new location – Nikhef. A strategic landscape for network expansion, Nikhef will enable us to augment our network capacity significantly. With improved low-latency peers and transit offerings for our customers, we are poised to facilitate unprecedented network efficiency.</p> <p>The Nikhef location is a noteworthy step towards bolstering our network’s redundancy, allowing us the agility to add more RoyaleHosting locations and expand our services further.</p> <h2>Welcoming 2024 🎇</h2> <p>Envisioning a future that reflects our growth and customer commitment, our 2024 plans are poised to raise the bar even higher. A core element of our goals is the public release of the much-awaited Shield Panel, empowering customers with advanced firewall access and ensuring optimal security.</p> <p>Similarly, the public launch of our Dedicated Panel aims to enhance the experience for dedicated customers, aligning perfectly with our commitment to quality service. Furthermore, with plans to unveil new physical data center locations, we are excited to offer more diversity and flexibility for our customers through colocation and VPS server deployment.</p> <p>While these exciting plans form the crux of our 2024 roadmap, we have the thrilling task of unveiling some non-disclosed strategies that promise to make RoyaleHosting’s journey in 2024 one of our most exciting years.</p> <h2>Farewell 2023 👋</h2> <p>As we bid adieu to 2023, we take this moment to appreciate our customers’ unwavering trust in RoyaleHosting, our team’s unrelenting efforts, and our shared journeys of success. We hope everyone had a wonderful holiday season and is ready to stride into an exhilarating 2024.</p> <p>Our goals for the coming year and beyond are to meet expectations and surpass them significantly. Cheers to RoyaleHosting’s past, present, and most importantly, to the many exciting years. Here’s to touching new heights of excellence and innovation together!</p> <p>Onward to 2024, and happy new year! 🥂</p>",1);function M(e){var t=z();a(28),o(e,t)}const te=Object.freeze(Object.defineProperty({__proto__:null,default:M,metadata:q},Symbol.toStringTag,{value:"Module"}));export{G as _,F as a,L as b,B as c,X as d,J as e,Y as f,Q as g,K as h,Z as i,ee as j,te as k};
